"""Re-compose into an empty isolated directory and compare every generated byte."""
from pathlib import Path
import tempfile,json,hashlib
import compose
R=Path(__file__).resolve().parents[1];D=R/'dist'
def inventory(root):return {p.relative_to(root).as_posix():hashlib.sha256(p.read_bytes()).hexdigest()for p in root.rglob('*')if p.is_file()and p.name not in ['WEB-MANIFEST.json','clean-reproduction.json']and 'qa'not in p.relative_to(root).parts}
with tempfile.TemporaryDirectory(prefix='slot-web-reproduction-')as td:
 compose.D=Path(td)/'dist';compose.build();a=inventory(D);b=inventory(compose.D);missing=sorted(set(a)^set(b));changed=sorted(k for k in set(a)&set(b)if a[k]!=b[k]);report={'passed':not missing and not changed,'files':len(a),'missing_or_extra':missing,'changed':changed,'scope':'Clean webpage generation from frozen imported model, all generated bytes compared except self-report and final manifest; not a fresh Blender regeneration'}
(R/'review/clean-reproduction.json').write_text(json.dumps(report,indent=2)+'\n');print(report);assert report['passed']
